import { gql } from "@apollo/client";

export default function SingleTemplate(props) {
  const post = props.data?.post;

  if (!post) {
    return (
      <div className="py-12 bg-gray-50 text-center">
        <div className="max-w-[1440px] mx-auto px-6">
          <h1 className="text-4xl font-bold text-gray-800 mb-6">Post Not Found</h1>
          <p className="text-gray-600">The post you’re looking for doesn’t exist or has been removed.</p>
          <a
            href="/blog"
            className="mt-4 inline-block px-6 py-3 bg-dark-blue text-white rounded hover:bg-blue-900 transition-colors"
          >
            Back to Blog
          </a>
        </div>
      </div>
    );
  }

  const { title, content } = post;

  return (
    <article className="py-12 bg-gray-50">
      <div className="max-w-[1440px] mx-auto px-6">
        <h1 className="text-4xl font-bold text-gray-800 mb-6 text-center">{title}</h1>
        <div
          className="prose prose-lg prose-dark-blue max-w-none mx-auto"
          dangerouslySetInnerHTML={{ __html: content }}
        />
      </div>
    </article>
  );
}

SingleTemplate.query = gql`
  query GetPost($uri: ID!) {
    post(id: $uri, idType: URI) {
      title
      content
    }
  }
`;

SingleTemplate.variables = (seedQuery, ctx) => {
  return {
    uri: seedQuery?.uri,
  };
};